"""Planted defects for confirm, abort, status and verify (design 6.3-6.5, 3.5c). Used by tests/planted/runner.py with test_confirm.py, test_abort.py, test_status.py, test_verify.py."""
B = "device/openwrt/newton-router/tests"
TC = [f"{B}/test_confirm.py"]
TA = [f"{B}/test_abort.py", f"{B}/test_abort_more.py", f"{B}/test_abort_exact.py"]
TS = [f"{B}/test_status.py"]
TV = [f"{B}/test_verify.py"]
MUTANTS = [
    ('C01', 'M26-like: the rpcd confirm is skipped (guard confirm only)', 'if "$UBUS" call uci confirm "{\\"ubus_rpc_session\\":\\"$sid\\"}" >/dev/null 2>&1; then', 'if true; then', TC),
    ('C02', 'M27: the guard confirm refusal is ignored (reports confirmed)', 'if [ "$rc" -ne 0 ] || [ "$gout" != "$expected" ]; then', 'if false; then', TC),
    ('C03', 'M28: the lost path is taken although the config is not post', 'if [ "$sha" = "$post_sha" ]; then', 'if true; then', TC),
    ('C04', 'RPCD_LOST shipped non-empty', "\nRPCD_LOST=''\n", "\nRPCD_LOST='5 6'\n", TC),
    ('C05', 'too-late: guard left boundary 4 instead of 5', '[ "$guard_left" -ge 5 ] || fail too-late 3', '[ "$guard_left" -ge 4 ] || fail too-late 3', TC),
    ('C06', 'too-late: rpcd deadline boundary 4 instead of 5', '[ "$(( rpcd_dl - UP_NOW ))" -ge 5 ] || fail too-late 3', '[ "$(( rpcd_dl - UP_NOW ))" -ge 4 ] || fail too-late 3', TC),
    ('C07', 'not-applied: the boot id check is skipped', '[ "$BOOT_ID_OUT" = "$boot_applied" ] || fail not-applied 1\n\tuptime_now\n\tguard_status', 'uptime_now\n\tguard_status', TC),
    ('C08', 'the program lock directory is not removed after confirm', 'if [ "$current_sid" = "$sid" ]; then\n\t\t\trm -rf "$LOCK"\n\t\tfi', 'if [ "$current_sid" = "$sid" ]; then\n\t\t\t:\n\t\tfi', TC),
    ('C09', 'last is not written by confirm', 'printf \'%s\\n\' "confirmed $sid" > "$R/tmp/newton/last"', ':', TC),
    ('C10', 'the rpcd save dir is not removed by confirm', '[ -n "$sdir" ] && rm -rf "$sdir"\n\tcrash_point\n\tprintf \'%s\\n\' "confirmed $sid"', 'crash_point\n\tprintf \'%s\\n\' "confirmed $sid"', TC),
    ('C11', 'the guard confirm line leaks to stdout', 'gout=$("$GUARD" confirm "$sid" </dev/null 2>/dev/null)\n\trc=$?', 'gout=$("$GUARD" confirm "$sid" </dev/null 2>/dev/null)\n\trc=$?\n\tprintf \'%s\\n\' "$gout"', TC),
    ('C12', 'confirm-incomplete: the guard restore is skipped', '"$GUARD" restore confirm-incomplete </dev/null >/dev/null 2>&1', ':', TC),
    ('C13', 'rpcd confirm failure: not refused', 'fail rpcd-confirm-failed 1 "$rc"\n\t\tfi\n\tfi\n\tgout=', ':\n\t\tfi\n\tfi\n\tgout=', TC),
    ('C14', 'no crash point after the rpcd-confirmed write (ok)', 'printf \'%s\\n\' ok > "$txn/rpcd-confirmed"\n\t\tcrash_point\n', 'printf \'%s\\n\' ok > "$txn/rpcd-confirmed"\n', TC),
    ('C15', 'confirm does not ignore HUP and PIPE (connection dropped during confirm)', 'cmd_confirm() {\n\tlocal sid="$1" txn applied boot_applied rpcd_dl guard_left gout first NL sha post_sha cf w rpcd_lost expected current_sid LOST rc sdir\n\ttrap \'\' HUP PIPE\n', 'cmd_confirm() {\n\tlocal sid="$1" txn applied boot_applied rpcd_dl guard_left gout first NL sha post_sha cf w rpcd_lost expected current_sid LOST rc sdir\n', TC),
    ('B01', 'M30: abort skips the guard restore in row 3', 'if [ "$G_W1" = pending ] && [ "$G_W2" = "$sid" ]; then\n\t\t\t\tabort_restore "$sid"\n\t\t\t\tif [ "$rpcd_rc" -ne 0 ]; then', 'if [ "$G_W1" = pending ] && [ "$G_W2" = "$sid" ]; then\n\t\t\t\tif [ "$rpcd_rc" -ne 0 ]; then', TA),
    ('B02', 'M31: abort deletes the health snapshot', 'rm -rf "$LOCK/$sid.txn"\n\tcrash_point\n\trm -f "$LOCK/$sid.applied"', 'rm -rf "$LOCK/$sid.txn" "$LOCK/$sid.health"\n\tcrash_point\n\trm -f "$LOCK/$sid.applied"', TA),
    ('B03', 'M51: a non-owner may abort an applied txn while the guard is pending for it', '[ "$g1" = pending ] && [ "$g2" = "$sid" ] && return 1', ':', TA),
    ('B04', 'stale age limit 2701', '[ $(( UP_NOW - stage_up )) -gt 2700 ] && return 0 || return 1', '[ $(( UP_NOW - stage_up )) -gt 2701 ] && return 0 || return 1', TA),
    ('B05', 'row 1: a failed guard is ignored', 'if [ "$G_W1" = failed ]; then\n\t\tfail inconsistent 1 "guard $G_LINE"\n\tfi', 'if false; then\n\t\tfail inconsistent 1 "guard $G_LINE"\n\tfi', TA),
    ('B06', 'abort leaves the txn directory', 'rm -rf "$LOCK/$sid.txn"\n\tcrash_point\n\trm -f "$LOCK/$sid.applied"', 'crash_point\n\trm -f "$LOCK/$sid.applied"', TA),
    ('B07', 'abort does not write last', 'printf \'%s\\n\' "aborted $sid $how" > "$R/tmp/newton/last"', ':', TA),
    ('B08', 'a non-owner is never refused', 'abort_stale "$txn" "$G_W1" "$G_W2" "$sid" || fail not-owner 3', ':', TA),
    ('B09', 'abort_restore accepts any guard answer', '[ "${gout%%"$NL"*}" = "restored $sid abort" ] || fail rollback-failed 1', ':', TA),
    ('B10', 'row 4: already-rolled-back test reversed', 'if [ "$base_c" = "$base_now" ]; then\n\t\t\t\thow=already-rolled-back\n\t\t\telse\n\t\t\t\thow=rolled-back-by-guard\n\t\t\tfi', 'if [ "$base_c" = "$base_now" ]; then\n\t\t\t\thow=rolled-back-by-guard\n\t\t\telse\n\t\t\t\thow=already-rolled-back\n\t\t\tfi', TA),
    ('B11', 'row 6 already-confirmed never fires', '[ "$post_c" = "$post_sha" ] && fail already-confirmed 1', ':', TA),
    ('B12', 'abort does not tick the guard for a non-owner', '"$GUARD" tick </dev/null >/dev/null 2>&1\n\t\tfi\n\tfi\n\tguard_status', ':\n\t\tfi\n\tfi\n\tguard_status', TA),
    ('B13', 'abort leaves the rpcd uci dir', '[ -n "$sdir" ] && rm -rf "$sdir"\n\tcrash_point\n\trm -rf "$LOCK/$sid.txn"', 'crash_point\n\trm -rf "$LOCK/$sid.txn"', TA),
    ('B14', 'abort leaves the helper-format .applied file', 'rm -f "$LOCK/$sid.applied"\n\tcrash_point\n\t[ "$keep_last" = keep ] || printf \'%s\\n\' "aborted $sid $how"', 'crash_point\n\t[ "$keep_last" = keep ] || printf \'%s\\n\' "aborted $sid $how"', TA),
    ('T01', 'M29: status does not tick the guard', '"$GUARD" tick </dev/null >/dev/null 2>&1 || :\n\tguard_status', 'guard_status', TS),
    ('T02', 'rule 5 (config = base with the guard pending) missing', '\t\t\telif [ "$c" = base ]; then\n\t\t\t\tword=rolled-back\n\t\t\t\tr=rolled-back\n', '', TS),
    ('T03', 'rule 8 (confirmed) never fires', 'if [ "$rule8" = 1 ] && [ "$c" = post ]; then', 'if false; then', TS),
    ('T04', 'boot always same', 'b=new\n\t\tfi', 'b=same\n\t\tfi', TS),
    ('T05', 'rule 4 ignores the session', 'if [ "$UP_NOW" -lt "$RPCD_DL" ] && session_live "$sid"; then', 'if [ "$UP_NOW" -lt "$RPCD_DL" ]; then', TS),
    ('T06', 'rule 7 (guard restored this SID) missing', '\t\telif [ "$rest_me" = 1 ]; then\n\t\t\tword=rolled-back\n\t\t\tr=-\n', '', TS),
    ('T07', 'rule 10 (last = confirmed) missing', '"confirmed $sid")\n\t\t\t\tword=confirmed\n\t\t\t\tr=-\n\t\t\t\t;;', '"confirmed $sid")\n\t\t\t\tword=gone\n\t\t\t\tr=-\n\t\t\t\t;;', TS),
    ('T08', 'rule 3: rpcd=lost reported as confirmed', '\t\t\t\tlost)\n\t\t\t\t\tword=applied-pending-confirm\n\t\t\t\t\tr=lost\n', '\t\t\t\tlost)\n\t\t\t\t\tword=applied-pending-confirm\n\t\t\t\t\tr=confirmed\n', TS),
    ('T09', 'rule 13 (no txn, guard pending for the SID) reports gone', '\t\t\t\telif [ "$pend_me" = 1 ]; then\n\t\t\t\t\tword=inconsistent\n', '\t\t\t\telif [ "$pend_me" = 1 ]; then\n\t\t\t\t\tword=gone\n', TS),
    ('T10', 'status guard=failed reason dropped', 'g="failed:$ROUTER_FIELD_OUT"', 'g="failed:-"', TS),
    ('V01', 'the ping step is skipped', 'run_bounded 10 "$PING" -c1 -W3 1.1.1.1 || verify_fail \'verify: ping -c1 -W3 1.1.1.1 failed\'', ':', TV),
    ('V02', 'the nslookup step is skipped', 'run_bounded 10 "$NSLOOKUP" openwrt.org 127.0.0.1 || verify_fail \'verify: nslookup openwrt.org 127.0.0.1 failed\'', ':', TV),
    ('V03', 'the health check failure is ignored', 'health_check_run "$sid" \'\' || verify_fail', 'health_check_run "$sid" \'\' || :', TV),
    ('V04', 'the ping bound is 100 s instead of 10', 'run_bounded 10 "$PING" -c1 -W3 1.1.1.1 ||', 'run_bounded 100 "$PING" -c1 -W3 1.1.1.1 ||', TV),
    ('V05', 'the probe budget is 250 s', 'if [ "$(( UP_NOW - start_up ))" -ge 25 ]; then', 'if [ "$(( UP_NOW - start_up ))" -ge 250 ]; then', TV),
    ('V06', 'DHCP 1 does not need the listener', '"$PIDOF" dnsmasq >/dev/null 2>&1 && \\\n\t\t\t\t"$NETSTAT" -lnup 2>/dev/null | grep -q \':67 .*/dnsmasq\' && return 0', '"$PIDOF" dnsmasq >/dev/null 2>&1 && return 0', TV),
    ('V07', 'a failing probe is ignored', '\tprobe_run\n\trc=$?\n\t[ "$rc" -eq 0 ] && return 0\n\tverify_fail "verify: probe $n failed: $PB_NAME $PB_REASON"', '\tprobe_run\n\treturn 0', TV),
    ('V08', 'verify does not need an applied txn', '[ -e "$txn/applied" ] || fail not-applied 1\n\tIFS= read -r applied 2>/dev/null < "$txn/applied" || applied=\n\t# shellcheck disable=SC2086  # word split is the parse for the applied line', '[ -e "$txn/applied" ] || :\n\tIFS= read -r applied 2>/dev/null < "$txn/applied" || applied=\n\t# shellcheck disable=SC2086  # word split is the parse for the applied line', TV),
    ('V09', 'DHCP 2 not checked', '\t\t2)\n\t\t\t"$PIDOF" dnsmasq >/dev/null 2>&1 && return 0\n\t\t\tverify_fail', '\t\t2)\n\t\t\treturn 0\n\t\t\tverify_fail', TV),
]
